class Solution:
    def addOne(self, head):
        if head is None:
            return ListNode(1)

        nodes = []
        current = head
        while current is not None:
            nodes.append(current)
            current = current.next

        carry = 1
        for node in reversed(nodes):
            total = node.val + carry
            node.val = total % 10
            carry = total // 10
            if carry == 0:
                break

        if carry == 1:
            return ListNode(1, head)

        return head
